class vDuOAM23R3(vDuOAM23R2):
    def __init__(self, con_details, need_all_info=False):
        super(vDuOAM23R3, self).__init__(con_details, need_all_info)
        self.swm_v1 = SWMv1(con_details)
        self.agent_v1 = Agentv1(con_details)

    @enforce_use_m2m_type
    def get_ald_state_data(self, ald_dn, timeout=30, raw=False):
        response = self.asm_licensed.get_ald_state_data(ald_dn=ald_dn, timeout=timeout)
        return response if raw else GetAldsResponseV1.from_object_dict(response)

    @enforce_use_m2m_type
    def get_loglink(self, loglink_dn, timeout=30):
        response = self.asm_licensed.get_loglink(loglink_dn=loglink_dn, timeout=timeout)
        return M2mLoglinkV1.from_object_dict(response)

    @enforce_use_m2m_type
    def set_ret_configuration(self, target_dn, timeout=30, use_m2m=True, raw=False, **kwargs):
        if use_m2m:
            response = self.fh_licensed_v1.set_ret_configuration(target_dn=target_dn,
                                                                 timeout=timeout,
                                                                 **kwargs)
        else:
            response = self.fh_v1.set_ret_configuration(target_dn=target_dn,
                                                        timeout=timeout,
                                                        **kwargs)
        return response if raw else Operation.from_object_dict(response)

    @enforce_use_m2m_type
    def get_ret_configuration_status(self, operation_id, timeout=30, use_m2m=True):
        if use_m2m:
            response = self.fh_licensed_v1.get_ret_configuration_status(operation_id=operation_id, timeout=timeout)
        else:
            response = self.fh_v1.get_ret_configuration_status(operation_id=operation_id, timeout=timeout)
        return RetCommonResult.from_object_dict(response)

    @enforce_use_m2m_type
    def create_ald_reset(self, target_dn, type='soft', timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            response = self.fh_licensed_v1.create_ald_reset(target_dn=target_dn, type=type, timeout=timeout)
        else:
            response = self.fh_v1.create_ald_reset(target_dn=target_dn, type=type, timeout=timeout)
        return response if raw else Operation.from_object_dict(response)

    @enforce_use_m2m_type
    def get_ald_reset_status(self, operation_id, timeout=30, use_m2m=True, raw=False):
        if use_m2m:
            response = self.fh_licensed_v1.get_ald_reset_status(operation_id=operation_id, timeout=timeout)
        else:
            response = self.fh_v1.get_ald_reset_status(operation_id=operation_id, timeout=timeout)
        return response if raw else Operation.from_object_dict(response)

    def trigger_sw_update(self, file_path, xml_file_name='TargetBD_EXD.xml', sw_update_type='ALD', sw_update_source='WEBEM',
                          timeout=30, operation_timeout=300):
        self.swm_v1.trigger_sw_update(file_path=file_path,
                                      xml_file_name=xml_file_name,
                                      sw_update_type=sw_update_type,
                                      sw_update_source=sw_update_source,
                                      timeout=timeout,
                                      operation_timeout=operation_timeout)

    def _get_ptp_status_in_mo_info(self, dist_name, key_name='syncStatus'):
        mo_info = self.get_managed_object_parameters_of_current_plan(dist_name)
        parameters = mo_info.parameters
        for p in parameters:
            if p.simple_parameter.name == key_name:
                return p.simple_parameter.value

    def _get_clock_dist(self, rannic):
        for clock_id in [1, 2]:
            _dist = rannic + '/CLOCK-%s' % clock_id
            mo_info = self.get_managed_object_parameters_of_current_plan(_dist)
            for p in mo_info.parameters:
                if p.simple_parameter.name == 'clockType' and p.simple_parameter.value == 'Host':
                    host_clock_dist = _dist
                    break
                if p.simple_parameter.name == 'clockType' and p.simple_parameter.value == 'RNIC':
                    rannic_clock_dist = _dist
                    break
        return host_clock_dist, rannic_clock_dist

    def _get_host_status(self, host_clock_dist):
        host_status = []
        for topp_r_id in range(1, 100):
            mo_info = None
            _host_clock_r_dist = host_clock_dist + '/CLOCK_R-%s' % topp_r_id
            try:
                mo_info = self.get_managed_object_parameters_of_current_plan(_host_clock_r_dist)
            except Exception:
                logging.info('dist name %s not found' % _host_clock_r_dist)
                pass
            if mo_info:
                sync_input = self._get_ptp_status_in_mo_info(_host_clock_r_dist, 'selectedSyncInput')
                if 'TOPP' in sync_input:
                    _host_topp_r_dist = host_clock_dist + '/TOP-1/TOPP-1/TOPP_R-%s' % topp_r_id
                    host_status.append({
                        'sync_status': self._get_ptp_status_in_mo_info(_host_clock_r_dist),
                        'lock_status': self._get_ptp_status_in_mo_info(_host_topp_r_dist, 'lockState'),
                        'host_targetDN': self._get_ptp_status_in_mo_info(_host_clock_r_dist, "targetDN")})
                if 'GNSS' in sync_input:
                    host_status.append({
                        'sync_status': self._get_ptp_status_in_mo_info(_host_clock_r_dist),
                        'host_targetDN': self._get_ptp_status_in_mo_info(_host_clock_r_dist, "targetDN")})
        return host_status

    def _get_rannic_status(self, rannic_clock_dist):
        rannic_status = []
        for topp_r_id in range(1, 100):
            mo_info = None
            _rannic_clock_r_dist = rannic_clock_dist + '/CLOCK_R-%s' % topp_r_id
            try:
                mo_info = self.get_managed_object_parameters_of_current_plan(_rannic_clock_r_dist)
            except Exception:
                logging.info('dist name %s not found' % _rannic_clock_r_dist)
                pass
            if mo_info:
                sync_input = self._get_ptp_status_in_mo_info(_rannic_clock_r_dist, 'selectedSyncInput')
                if 'TOPP' in sync_input:
                    _rannic_topp_r_dist = rannic_clock_dist + '/TOP-1/TOPP-1/TOPP_R-%s' % topp_r_id
                    rannic_status.append({
                        'rannic_targetDN': self._get_ptp_status_in_mo_info(_rannic_clock_r_dist, 'targetDN'),
                        'sync_status': self._get_ptp_status_in_mo_info(_rannic_clock_r_dist),
                        'lock_status': self._get_ptp_status_in_mo_info(_rannic_topp_r_dist, 'lockState')})
                if 'GNSS' in sync_input:
                    rannic_status.append({
                        'rannic_targetDN': self._get_ptp_status_in_mo_info(_rannic_clock_r_dist, 'targetDN'),
                        'sync_status': self._get_ptp_status_in_mo_info(_rannic_clock_r_dist)})
        return rannic_status

    def get_ptp_sync_status_from_plan(self, mrbts_id, timeout=30):  # noqa: C901
        # TODO: Functionality should be modified when transitioning to internal HTTP client
        sync_dist_name = None
        flag = 0
        for sync_id in range(1, 50):
            sync_dist_name = 'MRBTS-%s/MNL-1/MNLENT-1/SYNC-%s' % (mrbts_id, sync_id)
            try:
                mo_info = self.get_managed_object_parameters_of_current_plan(sync_dist_name, timeout=timeout)
                for p in mo_info.parameters:
                    if p.simple_parameter.name == 'profileType' and p.simple_parameter.value == 'RAC':
                        logging.info('find a rannic sync mo, dist name is %s' % sync_dist_name)
                        flag = 1
                        break
            except Exception:
                logging.info('dist name %s not exist' % sync_dist_name)
            if flag == 1:
                break
        result = []
        if sync_dist_name:
            _result = {'rannic_sync_dist_name': sync_dist_name}
            host_clock_dist, rannic_clock_dist = self._get_clock_dist(sync_dist_name)
            _result['host'] = self._get_host_status(host_clock_dist)
            _result['rannic'] = self._get_rannic_status(rannic_clock_dist)
            result.append(_result)
            return result

    def get_rnic_info_from_plan(self, timeout=30):
        return self.asm_v1.get_rnic_info_from_plan(timeout=timeout)

    def update_service_account_password(self, username, password, new_password, timeout=30):
        response = self.asm_v1.update_service_account_password(username=username,
                                                               password=password,
                                                               new_password=new_password,
                                                               timeout=timeout)
        return UpdateServiceAccountPasswordV1.from_object_dict(response)

    def reset_rannic(self, rannic_r_dn, timeout=30, raw=False, **kwargs):
        response = self.agent_v1.reset_rannic(rannic_r_dn=rannic_r_dn, timeout=timeout, **kwargs)
        return response if raw else ResetRannicResponseV1.from_object_dict(response)

    def get_rnic_rest_operation(self, operation_id, timeout=30, raw=False):
        response = self.agent_v1.get_rnic_rest_operation(operation_id=operation_id, timeout=timeout)
        return response if raw else GetResetRannicOperationResponseV1.from_object_dict(response)

    def delete_rnic_rest_operation(self, operation_id, timeout=30):
        self.agent_v1.delete_rnic_rest_operation(operation_id=operation_id, timeout=timeout)

    @enforce_use_m2m_type
    def start_l1_streaming_trace(self, cell_id, output_mode, traces_info, timeout=30, use_m2m=True):
        traces = [
            {key.split('_')[0] + ''.join(word.capitalize() for word in key.split('_')[1:]): value
            for key, value in trace.items()}
            for trace in traces_info
        ]
        if use_m2m:
            self.asm_licensed.start_l1_streaming_trace(cell_id=cell_id, output_mode=output_mode,
                                                       traces_info=traces, timeout=timeout)
        else:
            self.asm_v1.start_l1_streaming_trace(cell_id=cell_id,
                                                 output_mode=output_mode,
                                                 traces_info=traces,
                                                 timeout=timeout)

    @enforce_use_m2m_type
    def stop_l1_streaming_trace(self, cell_id, output_mode, traces_info, timeout=30, use_m2m=True):
        traces = [
            {key.split('_')[0] + ''.join(word.capitalize() for word in key.split('_')[1:]): value
            for key, value in trace.items()}
            for trace in traces_info
        ]
        if use_m2m:
            return self.asm_licensed.stop_l1_streaming_trace(cell_id=cell_id, output_mode=output_mode,
                                                             traces_info=traces, timeout=timeout)
        else:
            return self.asm_v1.stop_l1_streaming_trace(cell_id=cell_id,
                                                       output_mode=output_mode,
                                                       traces_info=traces,
                                                       timeout=timeout)

    @enforce_use_m2m_type
    def get_all_l1_streaming_traces(self, timeout=30, use_m2m=True):
        if use_m2m:
            response = self.asm_licensed.get_all_l1_streaming_traces(timeout=timeout)
        else:
            response = self.asm_v1.get_all_l1_streaming_traces(timeout=timeout)
        return list(map(GetAllL1StreamingTraceV1.from_object_dict, response))

    @enforce_use_m2m_type
    def remove_l1_streaming_trace_by_cell_id(self, cell_id, timeout=30, use_m2m=True):
        if use_m2m:
            return self.asm_licensed.remove_l1_streaming_trace_by_cell_id(cell_id=cell_id, timeout=timeout)
        else:
            return self.asm_v1.remove_l1_streaming_trace_by_cell_id(cell_id=cell_id, timeout=timeout)
